// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Place-assertion spec functions of property `system_output_range` -- one per
//! point its decoration binds (unbound points carry `true`, design D5).

#![allow(non_snake_case)]
#![allow(unused_imports)]

use data::*;
use vstd::prelude::*;

use crate::assertions::*;
use crate::system_state::SystemState;

verus! {

/** property system_output_range, bound 'at START' (place START)
  *   environment assumption: the system input is less than 10
  */
pub open spec fn sys_assert_system_output_range_START(st: SystemState) -> bool
{
  st.system_input < 10i32
}

/** property system_output_range, bound 'after top_a' (place after_top_a)
  *   the nested A establishes its output bound and B's input assumption
  */
pub open spec fn sys_assert_system_output_range_after_top_a(st: SystemState) -> bool
{
  ((st.system_input < 10i32) &&
    (st.top_a_output < 2i32 * st.system_input)) &&
    (st.top_a_output < 20i32)
}

/** property system_output_range, bound 'after top_b' (place after_top_b)
  *   the nested B establishes its output bound for C
  */
pub open spec fn sys_assert_system_output_range_after_top_b(st: SystemState) -> bool
{
  ((st.system_input < 10i32) &&
    (st.top_a_output < 2i32 * st.system_input)) &&
    (st.top_b_output < st.top_a_output + 15i32)
}

/** property system_output_range, bound 'after top_c' (place after_top_c)
  *   the nested top-level result is available and the input invariant is preserved
  */
pub open spec fn sys_assert_system_output_range_after_top_c(st: SystemState) -> bool
{
  (st.system_input < 10i32) &&
    (st.top_output < 50i32)
}

/** property system_output_range, bound 'after outer_a' (place after_outer_a)
  *   the above-top result is available and the input invariant is preserved
  */
pub open spec fn sys_assert_system_output_range_after_outer_a(st: SystemState) -> bool
{
  (st.system_input < 10i32) &&
    (st.system_output < 100i32)
}

/** property system_output_range, bound 'at END' (place END)
  *   the input invariant is preserved across the schedule boundary
  */
pub open spec fn sys_assert_system_output_range_END(st: SystemState) -> bool
{
  st.system_input < 10i32
}

} // verus!
